"""Get Provenance record."""
def get_provenance_record(
    ancestor_files: Any,
    caption: Any,
    statistics: Any,
    domains: Any,
    plot_type: Any = 'other'
) -> object {
    record = {
        'caption': caption,
        'statistics': statistics,
        'domains': domains,
        'plot_type': plot_type,
        'themes': ['phys'],
        'authors': ['weigel_katja'],
        'references': ['deangelis15nat'],
        'ancestors': ancestor_files
    };
    return record;
}

