test "t0" {
    assert (
        get_provenance_record(
            [
                'ancestors/input.nc',
                'ancestors/tas_Amon_EC-Earth3P-HR_hist-1950_r1i1p1f1_gr_200512-200611.nc'
            ],
            'This is a test',
            'This is a test',
            'This is a test'
        )
        == {
            'caption': 'This is a test',
            'statistics': 'This is a test',
            'domains': 'This is a test',
            'plot_type': 'other',
            'themes': ['phys'],
            'authors': ['weigel_katja'],
            'references': ['deangelis15nat'],
            'ancestors': [
                'ancestors/input.nc',
                'ancestors/tas_Amon_EC-Earth3P-HR_hist-1950_r1i1p1f1_gr_200512-200611.nc'
            ]
        }
    );;
}

